SELECT jsonb_build_object(
 'objects',(SELECT jsonb_agg(jsonb_build_object('kind',kind,'identity',identity,'hash',hash)ORDER BY kind,identity)FROM(
 SELECT 'relation'kind,n.nspname||'.'||c.relname identity,md5(jsonb_build_object('kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'options',c.reloptions,'view',CASE WHEN c.relkind IN('v','m')THEN pg_get_viewdef(c.oid,true)ELSE NULL END)::text)hash FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'AND c.relkind IN('r','p','v','m','S')
 UNION ALL SELECT 'schema',n.nspname,md5(jsonb_build_object('owner',pg_get_userbyid(n.nspowner),'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN'PUBLIC'ELSE pg_get_userbyid(x.grantee)END,'privilege',x.privilege_type,'grantable',x.is_grantable)ORDER BY pg_get_userbyid(x.grantor),CASE WHEN x.grantee=0 THEN'PUBLIC'ELSE pg_get_userbyid(x.grantee)END,x.privilege_type)FROM aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner)))x))::text)FROM pg_namespace n WHERE n.nspname='public'
 UNION ALL SELECT 'column',n.nspname||'.'||c.relname||'.'||a.attname,md5(jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'ordinal',a.attnum)::text)FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public'AND c.relkind IN('r','p','v','m')AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'function',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',md5(pg_get_functiondef(p.oid)||':'||pg_get_userbyid(p.proowner))FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'AND p.prokind IN('f','p')
 UNION ALL SELECT 'policy',n.nspname||'.'||c.relname||'.'||p.polname,md5(jsonb_build_object('cmd',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN'PUBLIC'ELSE pg_get_userbyid(r)END ORDER BY r)FROM unnest(p.polroles)r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))::text)FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('public','storage')
 UNION ALL SELECT 'constraint',n.nspname||'.'||c.relname||'.'||q.conname,md5(pg_get_constraintdef(q.oid,true)||':'||q.convalidated::text)FROM pg_constraint q JOIN pg_class c ON c.oid=q.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
 UNION ALL SELECT 'index',n.nspname||'.'||c.relname,md5(pg_get_indexdef(c.oid)||':'||i.indisvalid::text||':'||i.indisready::text)FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
 UNION ALL SELECT 'trigger',n.nspname||'.'||c.relname||'.'||t.tgname,md5(pg_get_triggerdef(t.oid,true)||':'||t.tgenabled::text)FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'AND NOT t.tgisinternal
 UNION ALL SELECT 'enum',n.nspname||'.'||t.typname,md5(jsonb_agg(e.enumlabel ORDER BY e.enumsortorder)::text)FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname='public'GROUP BY n.nspname,t.typname
 )objects),
 'publications',(SELECT coalesce(jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename)ORDER BY pubname,schemaname,tablename),'[]')FROM pg_publication_tables WHERE schemaname='public'),
 'privileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('object',object_name,'grantor',grantor,'grantee',grantee,'privilege',privilege,'grantable',grantable)ORDER BY object_name,grantor,grantee,privilege),'[]')FROM(
SELECT n.nspname||'.'||c.relname object_name,pg_get_userbyid(x.grantor)grantor,CASE WHEN x.grantee=0 THEN'PUBLIC'ELSE pg_get_userbyid(x.grantee)END grantee,x.privilege_type privilege,x.is_grantable grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S'THEN'S'ELSE'r'END::"char",c.relowner)))x WHERE n.nspname='public'AND c.relkind IN('r','p','v','m','S')
UNION ALL SELECT n.nspname||'.'||c.relname||'.'||a.attname,pg_get_userbyid(x.grantor),CASE WHEN x.grantee=0 THEN'PUBLIC'ELSE pg_get_userbyid(x.grantee)END,x.privilege_type,x.is_grantable FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(a.attacl)x WHERE n.nspname='public'AND a.attnum>0 AND NOT a.attisdropped
UNION ALL SELECT n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',pg_get_userbyid(x.grantor),CASE WHEN x.grantee=0 THEN'PUBLIC'ELSE pg_get_userbyid(x.grantee)END,x.privilege_type,x.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))x WHERE n.nspname='public')a),
 'default_privileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,''),'type',d.defaclobjtype,'grantor',pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN'PUBLIC'ELSE pg_get_userbyid(x.grantee)END,'privilege',x.privilege_type,'grantable',x.is_grantable)ORDER BY pg_get_userbyid(d.defaclrole),coalesce(n.nspname,''),d.defaclobjtype,x.privilege_type,CASE WHEN x.grantee=0 THEN'PUBLIC'ELSE pg_get_userbyid(x.grantee)END),'[]')FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl)x WHERE n.nspname='public'OR d.defaclnamespace=0),
 'owners',(SELECT jsonb_agg(jsonb_build_object('owner',owner,'relations',n)ORDER BY owner)FROM(SELECT pg_get_userbyid(c.relowner)owner,count(*)n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'GROUP BY c.relowner)x)
) AS inspection
